//! Root GPU executor for the concrete Oxide Qwen3-VL forward.
//!
//! Input is a fixture JSON generated by the real Qwen3-VL processor. This binary
//! runs the actual vision tower and shared dense decoder and writes the pooled
//! (or raw, depending on the fixture pool) rows as F32. It is a real device
//! path; CPU-only builds compile it but cannot execute it.

use cuda_core::{Context, Stream};
use infinity_backend_oxide::qwen3_vl_device::{Qwen3VlExecutor, Qwen3VlForward, VisionImage};
use serde::Deserialize;
use std::error::Error;
use std::path::{Path, PathBuf};
use std::sync::Arc;

#[derive(Deserialize)]
struct Fixture {
    #[serde(default)]
    checkpoint: Option<String>,
    #[serde(default)]
    name: Option<String>,
    ids: Vec<u32>,
    cumulative: Vec<u32>,
    media_positions: Option<[Vec<u32>; 3]>,
    #[serde(default)]
    images: Vec<FixtureImage>,
    #[serde(default = "last_token")]
    pool: String,
}

#[derive(Deserialize)]
struct FixtureImage {
    name: String,
    pixels: String,
    grid_thw: [usize; 3],
    merge_size: usize,
    token_start: usize,
}

fn last_token() -> String {
    "last_token".to_owned()
}

#[derive(Deserialize)]
struct Manifest {
    checkpoint: String,
    fixtures: Vec<Fixture>,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum FixtureFile {
    Single(Fixture),
    Manifest(Manifest),
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut args = std::env::args().skip(1);
    let fixture_path = args
        .next()
        .ok_or("usage: qwen3_vl_forward FIXTURE_OR_MANIFEST.json OUTPUT.f32 [FIXTURE_NAME]")?;
    let output_path = args
        .next()
        .ok_or("usage: qwen3_vl_forward FIXTURE_OR_MANIFEST.json OUTPUT.f32 [FIXTURE_NAME]")?;
    let selected = args.next();
    let parsed: FixtureFile = serde_json::from_slice(&std::fs::read(&fixture_path)?)?;
    let (checkpoint, fixture) = match parsed {
        FixtureFile::Single(fixture) => {
            let checkpoint = fixture
                .checkpoint
                .clone()
                .ok_or("single fixture JSON is missing checkpoint")?;
            (checkpoint, fixture)
        }
        FixtureFile::Manifest(manifest) => {
            let fixture = match selected.as_deref() {
                Some(name) => manifest
                    .fixtures
                    .into_iter()
                    .find(|fixture| fixture.name.as_deref() == Some(name))
                    .ok_or_else(|| format!("fixture {name} not found"))?,
                None => manifest
                    .fixtures
                    .into_iter()
                    .next()
                    .ok_or("manifest has no fixtures")?,
            };
            (manifest.checkpoint, fixture)
        }
    };
    let mut images = Vec::with_capacity(fixture.images.len());
    for image in fixture.images {
        let path = PathBuf::from(&image.pixels);
        let bytes = std::fs::read(&path)?;
        if bytes.len() % 4 != 0 {
            return Err(format!("{} is not an F32 file", path.display()).into());
        }
        let pixels = bytes
            .chunks_exact(4)
            .map(|chunk| f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]))
            .collect();
        images.push(VisionImage {
            name: image.name,
            pixels,
            grid_thw: image.grid_thw,
            merge_size: image.merge_size,
            token_start: image.token_start,
        });
    }
    let pool = match fixture.pool.as_str() {
        "cls" => infinity_v3_backend_core::Pool::Cls,
        "mean" => infinity_v3_backend_core::Pool::Mean,
        "last_token" => infinity_v3_backend_core::Pool::LastToken,
        other => return Err(format!("unsupported pool {other}").into()),
    };
    let input = Qwen3VlForward {
        ids: fixture.ids,
        cumulative: fixture.cumulative,
        images,
        media_positions: fixture.media_positions,
        pool,
        raw_tokens: false,
    };
    let context = Arc::new(Context::new(0)?);
    let stream: Arc<Stream> = context.new_stream()?;
    let mut executor = Qwen3VlExecutor::new(Path::new(&checkpoint), &context, &stream)?;
    let hidden = executor.forward(&input)?;
    let mut bytes = Vec::with_capacity(hidden.len() * 4);
    for value in hidden {
        bytes.extend_from_slice(&value.to_le_bytes());
    }
    std::fs::write(output_path, bytes)?;
    Ok(())
}
